일들 = input("일어난 일: ").split()
점수 = 0
목숨 = 3
def 판쓰기():
    print(f"보물 {점수} 목숨 {목숨}")
판쓰기()
for 일 in 일들:
    if 일 == "보물":
        점수 += 1
    elif 일 == "게":
        목숨 -= 1
    판쓰기()

점수 = int(input("점수: "))
try:
    with open("기록.txt") as 파일:
        최고 = int(파일.read())
except FileNotFoundError:
    최고 = 0
if 점수 > 최고:
    with open("기록.txt", "w") as 파일:
        print(점수, file=파일)
    print(f"새 기록 {점수}")
else:
    print(f"최고 {최고}")

