class 스위치:
    def __init__(self):
        self.켜짐 = False
    def 누르기(self):
        self.켜짐 = not self.켜짐
    def 상태(self):
        if self.켜짐:
            return "켜짐"
        return "꺼짐"

불 = 스위치()
번 = int(input("몇 번 누를까요? "))
for i in range(번):
    불.누르기()
print(불.상태())
